// Tolu's 20:00 report. Each sheet node ran once (Execute Once) with Always Output Data,
// so empty sheets give one empty item: filter those out.
const today = $today.toISODate();
const rows = n => $(n).all().map(i => i.json).filter(r => Object.keys(r).length);
const isToday = r => String(r.created_at ?? r.at ?? '').startsWith(today);
const naira = n => '₦' + Number(n).toLocaleString('en-NG');

const orders = rows('Orders').filter(r => isToday(r) && r.status === 'confirmed');
const revenue = orders.reduce((s, o) => s + (Number(o.total) || 0), 0);

const byProduct = {};
for (const o of orders) {
  let lines = [];
  try { lines = JSON.parse(o.items_json); } catch (e) {}
  for (const l of lines) {
    byProduct[l.name] ??= { name: l.name, unit: l.unit, qty: 0 };
    byProduct[l.name].qty += Number(l.qty) || 0;
  }
}
const top = Object.values(byProduct).sort((a, b) => b.qty - a.qty).slice(0, 3)
  .map(p => `${p.name} (${p.qty} ${p.unit})`).join(' · ') || 'none';

const LOW = 5;                                         // low-stock threshold
const low = rows('Price_List').filter(p => p.active !== 'no' && Number(p.stock) < LOW)
  .map(p => `${p.name} ${p.stock} ${p.unit}`).join(' · ') || 'none';

const cutoff = $now.minus({ hours: 2 });
const stale = rows('Pending').filter(p => p.status === 'open' && DateTime.fromISO(String(p.created_at)) < cutoff).length;
const waiting = rows('Conversation_Log').filter(r => isToday(r) && r.direction === 'to_tolu').length;

const text = [
  `🌙 Harvest Lane · ${$today.toFormat('ccc d LLL')}`,
  `Orders confirmed: ${orders.length} · Revenue: ${naira(revenue)}`,
  `Top: ${top}`,
  `Low stock (under ${LOW}): ${low}`,
  `Waiting for you: ${waiting} message(s) passed to you today`,
  `Open summaries older than 2 h: ${stale}`,
].join('\n');
return [{ json: { text } }];
